import fs from'node:fs';import path from'node:path';import assert from'node:assert/strict';import{guarded}from'./run-small-native-task-guarded-20261025.mjs';import{hash,json}from'./bounded-source-hash-20261026.mjs';
const stage='F:/VisibleMedicine/staging/20261027-review-area-navigation',site=stage+'/website',phase=process.argv[2];assert(['tests','browser-build'].includes(phase));const dir=stage+'/checks/'+phase+'-1',authored=json(stage+'/AUTHORED.json');function verify(){for(const r of authored.rows)assert.equal(hash(site+'/'+r.path),r.sha256);}verify();
const roots=['tests/clinical-review-discovery.test.ts','tests/clinical-review-area-navigation.test.ts','tests/clinical-review-inbox-link-context.test.mjs'];const script=path.resolve('build-review-area-browser-20261027.mjs').replaceAll('\\','/');assert(/^[A-Za-z0-9_:/.-]+$/.test(script));const command=phase==='tests'?'--max-old-space-size=512 --experimental-strip-types --test --test-reporter=tap --test-concurrency=1 '+roots.join(' '):'--max-old-space-size=384 '+script;
const i=json('CURRENT_CHECKPOINT.json');assert.deepEqual(i.activeWork.current.activeExecutionSessions,[]);i.activeWork.current.activeExecutionSessions=[{kind:'review-area-'+phase,driverPid:process.pid,evidence:dir}];fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(i,null,2)+'\n');const retire=()=>{const j=json('CURRENT_CHECKPOINT.json');if(j.activeWork.current.activeExecutionSessions[0]?.driverPid===process.pid){j.activeWork.current.activeExecutionSessions=[];fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(j,null,2)+'\n');}};const early=()=>{if(!fs.existsSync(dir+'/SUPERVISOR-HANDLE.json'))retire();};process.once('exit',early);
try{const run=await guarded({site,dir,command,heap:phase==='tests'?512:384,aggregate:phase==='tests'?1024:768,minimum:phase==='tests'?3072:2816});verify();const log=fs.readFileSync(dir+'/runner.stdout.log','utf8'),counts=phase==='tests'?Object.fromEntries(['tests','pass','fail','cancelled','skipped','todo'].map(k=>[k,Number([...log.matchAll(new RegExp('^# '+k+' (\\d+)','gm'))].at(-1)?.[1]??-1)])):null;const passing=run.passing&&(!counts||counts.tests>=6&&counts.tests===counts.pass&&counts.fail+counts.cancelled+counts.skipped+counts.todo===0);const result={at:new Date().toISOString(),passing,run,authored:{path:stage+'/AUTHORED.json',sha256:hash(stage+'/AUTHORED.json')},roots:phase==='tests'?roots:undefined,counts,normalPreviewChanged:false};fs.writeFileSync(dir+'/RESULT.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({result:dir+'/RESULT.json',passing,counts}));process.exitCode=passing?0:1;}finally{process.removeListener('exit',early);retire();}
